      other is TranscriptionResponse &&
          runtimeType == other.runtimeType &&
          text == other.text &&
          language == other.language &&
          duration == other.duration &&
          segments == other.segments;
}

/// A segment of transcribed audio with timing information.
class TranscriptionSegment {
  /// Segment index (0-based).
  final PlatformInt64 id;

  /// Start time in seconds.
  final double start;

  /// End time in seconds.
  final double end;

  /// Transcribed text for this segment.
  final String text;

  const TranscriptionSegment({
    required this.id,
    required this.start,
    required this.end,
    required this.text,
  });

  @override
  int get hashCode =>
      id.hashCode ^ start.hashCode ^ end.hashCode ^ text.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TranscriptionSegment &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          start == other.start &&
          end == other.end &&
          text == other.text;
}

/// Token-usage accounting returned by the provider on each completion / embedding call.
class Usage {
  /// Prompt tokens used. Defaults to 0 when absent (some providers omit this).
  final PlatformInt64 promptTokens;

  /// Completion tokens used. Defaults to 0 when absent (e.g. embedding responses).
  final PlatformInt64 completionTokens;

  /// Total tokens used. Defaults to 0 when absent (some providers omit this).
  final PlatformInt64 totalTokens;

  /// Breakdown of tokens used in the prompt, including cached tokens served
  /// at the provider's discounted cache-read rate. Absent when the provider
  /// does not return prompt-token details.
  final PromptTokensDetails? promptTokensDetails;

  /// Breakdown of tokens used in the completion, including reasoning tokens.
  /// Absent when the provider does not return completion-token details.
  final CompletionTokensDetails? completionTokensDetails;

  const Usage({
    required this.promptTokens,
    required this.completionTokens,
    required this.totalTokens,
    this.promptTokensDetails,
    this.completionTokensDetails,
  });

  @override
  int get hashCode =>
      promptTokens.hashCode ^
      completionTokens.hashCode ^
      totalTokens.hashCode ^
      promptTokensDetails.hashCode ^
      completionTokensDetails.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Usage &&
          runtimeType == other.runtimeType &&
          promptTokens == other.promptTokens &&
          completionTokens == other.completionTokens &&
          totalTokens == other.totalTokens &&
          promptTokensDetails == other.promptTokensDetails &&
          completionTokensDetails == other.completionTokensDetails;
}

@freezed
sealed class UserContent with _$UserContent {
  const UserContent._();

  /// Plain text content.
  const factory UserContent.text({required String field0}) = UserContent_Text;

  /// Array of content parts (text, images, documents, audio).
  const factory UserContent.parts({required List<ContentPart> field0}) =
      UserContent_Parts;
}

/// User message in the conversation.
class UserMessage {
  /// Message content as plain text or array of content parts (text, images, documents, audio).
  final UserContent content;

  /// Optional name for the user.
  final String? name;

  const UserMessage({required this.content, this.name});

  @override
  int get hashCode => content.hashCode ^ name.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UserMessage &&
          runtimeType == other.runtimeType &&
          content == other.content &&
          name == other.name;
}

/// Configuration for polling a batch until terminal status.
///
/// All time values are in seconds as `f64` so the struct bridges across FFI
/// boundaries without requiring a `Duration` shim.
class WaitForBatchConfig {
  /// Initial interval between polls, in seconds.
  final double initialIntervalSecs;

  /// Maximum interval between polls (backoff plateau), in seconds.
  final double maxIntervalSecs;

  /// Exponential backoff multiplier (e.g., 1.5 increases delay by 50% each poll).
  final double backoffMultiplier;

  /// Optional timeout in seconds — polling fails if this duration is exceeded.
  final double? timeoutSecs;

  const WaitForBatchConfig({
    required this.initialIntervalSecs,
    required this.maxIntervalSecs,
    required this.backoffMultiplier,
    this.timeoutSecs,
  });

  @override
  int get hashCode =>
      initialIntervalSecs.hashCode ^
      maxIntervalSecs.hashCode ^
      backoffMultiplier.hashCode ^
      timeoutSecs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WaitForBatchConfig &&
          runtimeType == other.runtimeType &&
          initialIntervalSecs == other.initialIntervalSecs &&
          maxIntervalSecs == other.maxIntervalSecs &&
          backoffMultiplier == other.backoffMultiplier &&
          timeoutSecs == other.timeoutSecs;
}

extension AssistantContentTextExt on AssistantContent {
  /// Returns the plain-text display value of this content.
  ///
  /// - If this is a Text variant, returns its string content verbatim.
  /// - If this is a Parts variant, concatenates the text fields from all text-type
  ///   parts, skipping non-text parts like images, audio, or refusals.
  /// - Otherwise returns an empty string.
  String text() {
    return switch (this) {
      AssistantContent_Text(:final field0) => field0,
      AssistantContent_Parts(:final field0) => _extractTextFromContentParts(
        field0,
      ),
      _ => '',
    };
  }
}

/// Helper: Extract and concatenate text from content parts.
/// Expects parts to be a List of sealed class instances (typically ContentPart
/// or similar union types where each variant is a sealed class, e.g. ContentPart_Text).
/// Only instances of *_Text variants (containing a text field) contribute to output.
String _extractTextFromContentParts(List<dynamic> parts) {
  final sb = StringBuffer();
  for (final part in parts) {
    // For FRB-generated sealed class instances, we can check the runtime type
    // and access properties dynamically. Sealed class variants follow the pattern
    // TypeName_VariantName, and text-type variants have a 'text' property.
    final typeString = part.runtimeType.toString();
    // Check if this is a text-type variant (e.g., 'ContentPart_Text(...)' or similar)
    if (typeString.contains('_Text')) {
      try {
        // Use dynamic access to get the 'text' field from the variant instance
        final text = (part as dynamic).text;
        if (text is String) {
          sb.write(text);
        }
      } catch (_) {
        // If field access fails, skip this part (it's not actually a text variant)
        continue;
      }
    }
  }
  return sb.toString();
}
